class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        # Forced chars from 'T' windows
        forced = [''] * L
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    c = str2[j]
                    if forced[pos] and forced[pos] != c:
                        return ""
                    forced[pos] = c
        # Prepare windows for 'F'
        windows = []
        pos_to_windows = [[] for _ in range(L)]
        for i, ch in enumerate(str1):
            if ch == 'F':
                w = {'rem': m, 'diff': False, 'idx': i}
                windows.append(w)
                for j in range(m):
                    pos_to_windows[i + j].append(w)
        word = []
        for p in range(L):
            # Determine forbidden chars
            forbid = set()
            # Check windows that will need this position to be different
            for w in pos_to_windows[p]:
                offset = p - w['idx']
                if w['rem'] == 1 and not w['diff']:
                    forbid.add(str2[offset])
            # Decide character
            if forced[p]:
                c = forced[p]
                if c in forbid:
                    return ""
            else:
                # pick smallest not in forbid
                c = None
                for ch in map(chr, range(ord('a'), ord('z')+1)):
                    if ch not in forbid:
                        c = ch
                        break
                if c is None:
                    return ""
            word.append(c)
            # Update windows
            for w in pos_to_windows[p]:
                offset = p - w['idx']
                w['rem'] -= 1
                if c != str2[offset]:
                    w['diff'] = True
        return "".join(word)
