    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it)); M = int(next(it)); S = int(next(it)); T = int(next(it))
    except StopIteration:
        return
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        dist = [-1]*(N+1)
        q = deque([start])
        dist[start] = 0
        while q:
            v = q.popleft()
            for to in adj[v]:
                if dist[to] == -1:
                    dist[to] = dist[v]+1
                    q.append(to)
        return dist

