class Solution:
    def permute(self, n: int, k: int):
        from math import factorial
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odds = [i for i in range(1, n + 1) if i % 2 == 1]
        evens = [i for i in range(1, n + 1) if i % 2 == 0]
        total = 0
        if n == 1:
            total = 1
        else:
            total = fact[(n + 1) // 2] * fact[n // 2] * 2

        if k > total:
            return []

        res = []
        used = set()
        last_parity = None  # None for first position

        for pos in range(1, n + 1):
            for num in range(1, n + 1):
                if num in used:
                    continue
                p = num % 2
                if last_parity is not None and p == last_parity:
                    continue
                # count remaining
                rem_odds = len([x for x in odds if x not in used and x != num])
                rem_evens = len([x for x in evens if x not in used and x != num])
                cnt = fact[rem_odds] * fact[rem_evens]
                if k <= cnt:
                    res.append(num)
                    used.add(num)
                    last_parity = p
                    break
                else:
                    k -= cnt
        return res
